/**
 * 上次出片距今秒数；None = 这条流水线还没出过任何片。
 */
sinceLastFinish: number | null; 
/**
 * 最近 12 小时逐小时出片数，`[0]` 是最近一小时。趋势比总数有用。
 */
hourly: number[]; 
/**
 * 按最近 6 小时的实测速度估算：把当前在跑的全部收完还要多久（秒）。
 * 速度为 0 时是 None —— **不编数字**，「还需 ∞」不如老实说估不出来。
 */
etaSecs: number | null; 
/**
 * 下一条到点查询还有多少秒（让人知道界面不是死的，只是在省着问）。
 */
